// Validate và chuẩn hóa dữ liệu đơn hàng
const data = $input.first().json;

// Kiểm tra thông tin bắt buộc
const requiredFields = ['customerName', 'phone', 'product', 'quantity', 'deliveryAddress', 'deliveryTime'];
const missingFields = requiredFields.filter(f => !data[f]);

if (missingFields.length > 0) {
  return [{
    json: {
      success: false,
      error: `Thiếu thông tin: ${missingFields.join(', ')}`,
      missingFields: missingFields
    }
  }];
}

// Format đơn hàng
const order = {
  orderId: `DH${Date.now().toString(36).toUpperCase()}${Math.random().toString(36).substring(2, 6).toUpperCase()}`,
  customerName: data.customerName.trim(),
  phone: data.phone.trim(),
  email: data.email || '',
  product: data.product.trim(),
  quantity: parseInt(data.quantity) || 1,
  price: parseFloat(data.price) || 0,
  totalAmount: (parseInt(data.quantity) || 1) * (parseFloat(data.price) || 0),
  deliveryAddress: data.deliveryAddress.trim(),
  deliveryTime: data.deliveryTime,
  note: data.note || '',
  specialRequest: data.specialRequest || '',
  status: 'pending',
  source: data.source || 'webhook',
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  giftWrap: data.giftWrap || false,
  cardMessage: data.cardMessage || '',
  paymentMethod: data.paymentMethod || 'cod',
  estimatedDelivery: data.estimatedDelivery || ''
};

console.log(`[ORDER] Đơn hàng mới: ${order.orderId} - ${order.customerName} - ${order.product} x${order.quantity}`);

return [{ json: order }];

// Kiểm tra nếu thiếu thông tin thì dừng xử lý
const data = $input.first().json;

if (data.success === false) {
  // Trả về lỗi cho webhook
  return [{
    json: data
  }];
}

return [{
  json: {
    ...data,
    totalFormatted: (data.totalAmount || 0).toLocaleString('vi-VN') + '₫',
    priceFormatted: (data.price || 0).toLocaleString('vi-VN') + '₫'
  }
}];

// Gửi phản hồi lỗi cho webhook
const data = $input.first().json;
return [{
  json: {
    orderId: null,
    success: false,
    message: data.error || 'Dữ liệu không hợp lệ',
    missingFields: data.missingFields || []
  }
}];

// Lưu đơn hàng vào file/Google Sheet (có thể thay bằng database)
// Ở đây dùng static data để lưu tạm
const data = $input.first().json;

// Lấy danh sách đơn hàng hiện tại từ workflow data
const orders = $getWorkflowStaticData('global')['orders'] || [];

// Thêm đơn hàng mới
orders.push({
  ...data,
  id: orders.length + 1
});

// Giới hạn lưu 100 đơn gần nhất
if (orders.length > 100) {
  orders.splice(0, orders.length - 100);
}

$getWorkflowStaticData('global')['orders'] = orders;

console.log(`[STORAGE] Đã lưu đơn hàng: ${data.orderId}. Tổng số đơn: ${orders.length}`);

return [{ json: { ...data, saved: true, totalOrders: orders.length } }];

// Gửi xác nhận đến khách hàng qua Telegram
const data = $input.first().json;

const customerMessage = `✅ *XÁC NHẬN ĐƠN HÀNG*

📋 *Mã đơn:* ${data.orderId}
👤 *Khách hàng:* ${data.customerName}
🌸 *Sản phẩm:* ${data.product} x${data.quantity}
💰 *Tổng tiền:* ${data.totalFormatted}
🏠 *Địa chỉ giao:* ${data.deliveryAddress}
🕐 *Thời gian:* ${data.deliveryTime}
💳 *Thanh toán:* ${data.paymentMethod === 'cod' ? 'Tiền mặt (COD)' : 'Chuyển khoản'}

📝 *Ghi chú:* ${data.note || 'Không có'}

Cảm ơn bạn đã đặt hàng tại Hoa Tươi Thanh Ngọc! 🌸
Chúng tôi sẽ giao hàng đúng hẹn và kèm thiệp miễn phí.

📞 *Hotline:* 0934 926 092 (nếu cần thay đổi đơn hàng)`;

return [{
  json: {
    chatId: data.customerChatId,
    text: customerMessage,
    type: 'customer_confirmation'
  }
}];

// Chuẩn bị thông báo cho Admin (chủ shop)
const data = $input.first().json;

// Admin chat ID - cần cập nhật sau khi test
const ADMIN_CHAT_IDS = []; // TODO: Thêm chat ID của chủ shop

// Chi tiết đơn hàng
const orderDetail = `🏪 *ĐƠN HÀNG MỚI - CẦN XỬ LÝ*

📋 *Mã đơn:* ${data.orderId}
🆔 *ID:* ${data.id}
📅 *Thời gian:* ${new Date(data.createdAt).toLocaleString('vi-VN')}
📱 *Nguồn:* ${data.source}

👤 *Khách hàng:* ${data.customerName}
📞 *SĐT:* ${data.phone}
✉️ *Email:* ${data.email || 'Không có'}

🌸 *Sản phẩm:* ${data.product}
🔢 *Số lượng:* ${data.quantity}
💰 *Đơn giá:* ${data.priceFormatted}
💵 *Tổng tiền:* ${data.totalFormatted}
💳 *Thanh toán:* ${data.paymentMethod === 'cod' ? 'COD' : 'Chuyển khoản'}

🏠 *Địa chỉ giao:* ${data.deliveryAddress}
🕐 *Giao lúc:* ${data.deliveryTime}
📝 *Ghi chú:* ${data.note || 'Không có'}
🎁 *Thiệp:* ${data.cardMessage ? `"${data.cardMessage}"` : 'Không'}

⚠️ *Hành động:* Gọi xác nhận đơn hàng với khách!
👉 Hotline: 0934 926 092`;

// Trả về dữ liệu để gửi đến admin (bỏ qua nếu chưa có admin chat ID)
if (ADMIN_CHAT_IDS.length === 0) {
  console.log('[ADMIN] Chưa cấu hình admin chat ID. Bỏ qua gửi thông báo.');
  return [{ json: { ...data, adminNotified: false, reason: 'No admin chat IDs configured' } }];
}

// Gửi đến từng admin
const results = ADMIN_CHAT_IDS.map(adminId => ({
  chatId: adminId,
  text: orderDetail,
  type: 'admin_notification'
}));

return results;

// Tổng hợp kết quả và trả về cho webhook
const inputs = $input.all();
const data = inputs[0].json;

// Kiểm tra nếu có notify admin không
const adminNotified = data.adminNotified !== false;

return [{
  json: {
    success: true,
    orderId: data.orderId,
    message: `Đơn hàng ${data.orderId} đã được tạo thành công! Nhân viên sẽ liên hệ xác nhận trong ít phút.`,
    order: {
      id: data.orderId,
      customerName: data.customerName,
      product: data.product,
      quantity: data.quantity,
      total: data.totalFormatted,
      deliveryAddress: data.deliveryAddress,
      deliveryTime: data.deliveryTime,
      status: 'pending',
      createdAt: data.createdAt
    }
  }
}];
